function SettingBindPhonePanel:Update()
    if Utils.TouchCount() > 0 and (not self.__closing) then
        local positionV = Utils.GetInputDownPos()
        local position = Vector2.New(positionV.x, positionV.y)
        if position ~= Vector2.zero then
            local camera = UIModule.RootCanvas.canvas.worldCamera
            local isInRect = RectTransformUtility.RectangleContainsScreenPoint(self.DropDown, position, camera)
            local isActive = KTool.IsActive(self.DropDown.gameObject)
            local isInRect1 = isActive and RectTransformUtility.RectangleContainsScreenPoint(self.DropDown, position, camera)
            if not (isInRect or isInRect1) then
                self.__closing = true
                CfUtils.SetActive(self.DropDown, false)
            end
        end
    end
end

