--region init
function SettingBindPhonePanel:InitHandler()
    SetButtonAction(self.BtnClose, Bind(self, self.BtnCloseClickCallback))
    SetButtonAction(self.BtnCloseBack, Bind(self, self.BtnCloseClickCallback))
    SetButtonAction(self.Toggle, Bind(self, self.ToggleOnClickCallback))
    SetButtonAction(self.BtnGetCode, Bind(self, self.BtnGetCodeOnClickCallback))
    SetButtonAction(self.FontStyleButton, Bind(self, self.BtnConfirmOnClickCallback))
    SetListViewAction(self.ScrollView, Bind(self, self.OnGetItemByIndex), CellName)
    self.PhoneInputField.onValueChanged:AddListener(Bind(self, self.OnPhoneInputFieldChanged))
    self.CodeInputField.onValueChanged:AddListener(Bind(self, self.OnCodeInputFieldChanged))
    local scr = CfUtils.GetLuaScr(self.LabelGroup, Constants.UILuaTablePath.ScreenToggle)
    if isNotNull(scr) then
        scr.onChangeCB = Bind(self, self.OnToggleChangeHandler)
    end
end

function SettingBindPhonePanel:InitData()
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    self._phone = userComponent.userInfo.phone
    self._phoneAreaCodeConf = CfUtils.GetCf(AutoIds.IdSetting6262, "PhoneAreaCodeVo", true)
    local initParams = self.controller.Argument.parameters or {}
    self._confirmCB = initParams.cb
    local id = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 32).num
    local index = 1
    for i, v in ipairs(self._phoneAreaCodeConf) do
        if checkInt(v.regionsId) == checkInt(id) then
            index = i
            break
        end
    end
    self._selectedAreaCode = index
end

function SettingBindPhonePanel:InitView()
    self:RefreshUI()
end
