--region handler
---关闭按钮点击回调
function SettingBindPhonePanel:BtnCloseClickCallback()
    UIModule.CloseDialog(self.controller)
end

---点击回调
function SettingBindPhonePanel:ToggleOnClickCallback()
    if not self.__closing then return end
    
    self.__closing = false
    self:RefreshListView()
    CfUtils.SetActive(self.DropDown, true)
end

---获取验证码按钮点击回调
function SettingBindPhonePanel:BtnGetCodeOnClickCallback()
    if self._cd > 0 then
        return
    end
    
    if not self:CheckBtnGetCodeStatus(true) then
        return
    end
    
    local phone = self:GetFullPhone()
    GameUtils.Request(Interfaces.SendBindPhoneVerifyCode, {phone = phone}, Bind(self, self.SendCodeResponseHandler))
end

---检查获取验证码按钮状态
function SettingBindPhonePanel:CheckBtnGetCodeStatus(isShowTips)
    if not Utils.IsLengthRange(self.PhoneInputField.text, 6, 15) then
        if isShowTips then
            GameUtils.Toast(localize('请输入正确的手机号'))
        end
        return false
    end

    ---@type ScreenToggle
    local env = CfUtils.GetLuaScr(self.LabelGroup, Constants.UILuaTablePath.ScreenToggle)
    if env and not env.isOn then
        if isShowTips then
            GameUtils.Toast(localize('请勾选隐私协议'))
        end
        return false
    end
    
    return true
end

---确认按钮点击回调
function SettingBindPhonePanel:BtnConfirmOnClickCallback()
    local code = self.CodeInputField.text
    if string.len(code) ~= 6 then
        GameUtils.Toast(localize('请输入6位验证码'))
        return
    end
    
    local phone = self:GetFullPhone()
    GameUtils.Request(Interfaces.BindPhone, {phone = phone, code = code}, Bind(self, self.BindPhoneResponseHandler))
end

---发送验证码response处理
function SettingBindPhonePanel:SendCodeResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end
    
    self._cd = VerificationCodeCD
    self:StartTimer()
end

function SettingBindPhonePanel:BindPhoneResponseHandler(request, response)
    if checkNumber(response.errCode) ~= 0 then return end
    local rewards = checkTable(response.data.rewards)
    if next(rewards) then
        GoodsUtils.DrawRewards(rewards)
        UIModule.OpenDialog({ id = Constants.UITypeIds.UICommonRewardPop, parameters = { rewards = rewards } })
    end
        
    local phone = self:GetFullPhone()
    local userComponent = GameUtils.GetEntityCompByType(ECSComponentType.Constants.UserComponent)
    userComponent.userInfo.phone = phone
    self._confirmCB(phone)
    UIModule.CloseDialog(self.controller)
end

---列表处理
function SettingBindPhonePanel:OnGetItemByIndex(loopListView, luaIndex)
    local cell = loopListView:NewListViewItem(CellName)
    local data = self._phoneAreaCodeConf[luaIndex]
    if not isNull(cell) then
        local scr = CfUtils.GetLuaScr(cell, "Game.UI.Setting.SettingBindPhoneCell")
        if not isNull(scr) then
            scr:RefreshCell(data, luaIndex, luaIndex == self._selectedAreaCode, Bind(self, self.OnClickCellHandler))
        end
    end
    return cell
end

---cell点击回调
function SettingBindPhonePanel:OnClickCellHandler(index)
    self._selectedAreaCode = index
    self:RefreshAreaCode()
    self.__closing = true
    CfUtils.SetActive(self.DropDown, false)
end

---手机号输入框改变回调
function SettingBindPhonePanel:OnPhoneInputFieldChanged(text)
    self:RefreshSendVerificationCodeBtn()
    self:RefreshConfirmBtn()
end

---验证码输入框改变回调
function SettingBindPhonePanel:OnCodeInputFieldChanged(text)
    self:RefreshConfirmBtn()
end

---toggle改变回调
function SettingBindPhonePanel:OnToggleChangeHandler(isOn)
    self:RefreshSendVerificationCodeBtn()
    self:RefreshConfirmBtn()
end
