--region private
---刷新UI
function SettingBindPhonePanel:RefreshUI()
    self:RefreshListView()
    self:RefreshAreaCode()
    self:RefreshSendVerificationCodeBtn()
    self:RefreshConfirmBtn()
end

---刷新列表
function SettingBindPhonePanel:RefreshListView()
    GameUtils.ReloadData(self.ScrollView, #self._phoneAreaCodeConf)
end

---刷新区号
function SettingBindPhonePanel:RefreshAreaCode()
    local areaCodeData = self._phoneAreaCodeConf[self._selectedAreaCode]
    if not isNull(areaCodeData) then
        CfUtils.FillText(self.ToggleText, "+" .. areaCodeData.regionsId)
    end
end

---刷新发送验证码按钮
function SettingBindPhonePanel:RefreshSendVerificationCodeBtn()
    if self._cd <= 0 then
        if self:CheckBtnGetCodeStatus(false) then
            CfUtils.SetUISwitchImage(self.BtnGetCode, 1)
        else
            CfUtils.SetUISwitchImage(self.BtnGetCode, 2)
        end
        CfUtils.FillText(self.BtnGetCodeText, localize('获取验证码'))
        return
    end

    CfUtils.SetUISwitchImage(self.BtnGetCode, 2)
    CfUtils.FillText(self.BtnGetCodeText, string.format("%ds", checkInt(self._cd)))
end

---刷新确认按钮
function SettingBindPhonePanel:RefreshConfirmBtn()
    local text = nil
    if tostring(self._phone) ~= '' then
        CfUtils.SetActive(self.HarvestAnim, false)
        CfUtils.SetActive(self.TextState1, false)
        CfUtils.SetActive(self.State2, true)
        CfUtils.FillText(self.TextPhoneNum, self._phone)
        text = localize('确认更换')
    else
        CfUtils.SetActive(self.HarvestAnim, true)
        local goodsId = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 30).num
        local goodsNum = CfUtils.GetCfVo(AutoIds.IdSetting10, "BaseArgVo", 31).num
        local goodsVo = GoodsConfMgr:GetInstance():GetGoodsVoById(goodsId)
        CfUtils.FillImage(self.ImgGoodIcon, goodsVo.photoPath)
        CfUtils.FillText(self.GoodsTxtNum, goodsNum) 
        CfUtils.SetActive(self.TextState1, true)
        CfUtils.SetActive(self.State2, false)
        text = localize('确认绑定')
    end

    local code = self.CodeInputField.text
    if self:CheckBtnGetCodeStatus(false) and string.len(code) == 6 then
        CfUtils.SetButtonStyle(self.FontStyleButton, "B3", text)
    else
        CfUtils.SetButtonStyle(self.FontStyleButton, "B17", text)
    end
end

---获取完整手机号
function SettingBindPhonePanel:GetFullPhone()
    local areaCodeData = self._phoneAreaCodeConf[self._selectedAreaCode]
    if isNull(areaCodeData) then return end
    
    return string.format("%s%s%s%s", "+", areaCodeData.regionsId, "-", self.PhoneInputField.text)
end

---开启定时器
function SettingBindPhonePanel:StartTimer()
    self:StopTimer()

    self._timer =  CDTimerModule.GetInstance():AddCD(1, function(count, id)
        self._cd = self._cd - 1
        self:RefreshSendVerificationCodeBtn()
    end, self._cd, true, true)

    self._timer.OnRemove =  function(count, id)
        self._cd = 0
    end
end

---关闭定时器
function SettingBindPhonePanel:StopTimer()
    if isNull(self._timer) then
        return
    end

    CDTimerModule.GetInstance():RemoveCD(self._timer)
    self._timer = nil 
end

--endregion private

return SettingBindPhonePanel